use std::io::*;

trait Shape {
    fn name(&self) -> &str;
    fn corners(&self) -> u32;
    fn double_area(&self) -> u128;
}

struct S {
    n: String,
    c: u32,
    d: u128,
}

impl Shape for S {
    fn name(&self) -> &str {
        &self.n
    }
    fn corners(&self) -> u32 {
        self.c
    }
    fn double_area(&self) -> u128 {
        self.d
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut shapes: Vec<Box<dyn Shape>> = Vec::new();
    for line in s.lines() {
        let w: Vec<&str> = line.split_whitespace().collect();
        if w.is_empty() {
            continue;
        }
        let v: Vec<u128> = w[1..].iter().map(|x| x.parse().unwrap_or(0)).collect();
        let g = |i: usize| v.get(i).copied().unwrap_or(0);
        let (c, d) = match w[0] {
            "square" => (4, 2 * g(0) * g(0)),
            "rect" => (4, 2 * g(0) * g(1)),
            "rtri" => (3, g(0) * g(1)),
            "trap" => (4, (g(0) + g(1)) * g(2)),
            _ => continue,
        };
        shapes.push(Box::new(S { n: w[0].to_string(), c, d }));
    }
    let mut total = 0u128;
    let mut best: Option<usize> = None;
    for (i, sh) in shapes.iter().enumerate() {
        println!("{} corners={} area2={}", sh.name(), sh.corners(), sh.double_area());
        total += sh.double_area();
        if best.map_or(true, |b| sh.double_area() > shapes[b].double_area()) {
            best = Some(i);
        }
    }
    println!("total area2={}", total);
    match best {
        Some(b) => println!("largest={} area2={}", shapes[b].name(), shapes[b].double_area()),
        None => println!("largest=none"),
    }
}

